fn is_sorted(arr: &Vec<i32>) -> bool {
    // Requires that the input array is not empty
    // Ensures that the function returns true if the array is sorted, false otherwise
    // Invariant: For all indices i in the range 0..len-1, arr[i] <= arr[i + 1] holds if the function returns true
    // Decreases clause: The length of the array decreases as we iterate
    // The loop invariant will be maintained throughout the loop execution

    assert!(arr.len() > 0); // Ensure the array is not empty

    let len = arr.len();
    // Loop invariant: For all indices j in the range 0..i, arr[j] <= arr[j + 1] holds
    // We will maintain this invariant throughout the loop
    for i in 0..len - 1 {
        // Assert that the current index is valid
        assert!(i < len - 1);
        
        // Check if the current element is greater than the next
        if arr[i] > arr[i + 1] {
            return false; // If any element is greater than the next, return false
        }
    }
    true // If we complete the loop without finding any issues, return true
}

fn main() {
    let arr1 = vec![1, 2, 2, 3, 4];
    let arr2 = vec![1, 3, 2, 4];
    
    // The following calls to is_sorted should respect the specifications
    println!("{}", is_sorted(&arr1)); // Should print true
    println!("{}", is_sorted(&arr2)); // Should print false
}